<?php
session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/../includes/auth.php';require_login();if(!is_admin()){http_response_code(403);exit('Acesso restrito.');}if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:denuncias.php');exit;}check_csrf();
$pdo=db();$id=(int)($_POST['id']??0);$acao=(string)($_POST['acao']??'');$res=trim((string)($_POST['resposta']??''));$map=['assumir'=>'Em avaliação','aprovar'=>'Aprovado','recusar'=>'Recusado'];
if($id<1||!isset($map[$acao])){header('Location:denuncias.php');exit;}$status=$map[$acao];$pdo->beginTransaction();$pdo->prepare('UPDATE denuncias SET status=?,admin=?,resposta=? WHERE id=?')->execute([$status,player_nick(),$res,$id]);$pdo->prepare('INSERT INTO denuncia_historico(denuncia_id,admin,status,resposta) VALUES(?,?,?,?)')->execute([$id,player_nick(),$status,$res]);$q=$pdo->prepare('SELECT denunciante FROM denuncias WHERE id=?');$q->execute([$id]);$den=$q->fetchColumn();if($den){$msg='Sua denúncia #'.$id.' está como '.$status.'.';if($res!=='')$msg.=' Resposta: '.$res;$pdo->prepare('INSERT INTO notificacoes(nick,titulo,mensagem) VALUES(?,?,?)')->execute([$den,'Atualização de denúncia',$msg]);}$pdo->commit();header('Location:denuncias.php');exit;